func loadBenchmarkEvidenceFixture(t *testing.T, name string) map[string]any {
	t.Helper()

	repoRoot := benchRepoRoot(t)
	raw, err := os.ReadFile(filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", name))
